'use strict';
// convert.js: the plugin's Claude Code files (agents, commands, skills) in the form OpenCode 2.x
// reads. One source: these are generated by install.js, never edited by hand.
//
// What changes, and why:
// - Agents: OpenCode reads a file with any V2 field ("permissions") as V2 and IGNORES its V1
//   fields, so the frontmatter is rewritten whole. `tools` becomes deny rules for what the agent
//   wasn't given; `model: sonnet` is dropped (not a valid OpenCode model, and a subagent without
//   one uses its caller's); `name` comes from the file name; `color` is dropped.
// - Commands: only `description` is kept (argument-hint and allowed-tools have no equivalent), the
//   ${CLAUDE_PLUGIN_ROOT} placeholder becomes the clone's real path, and a note says what differs.
// - Skills: the body is untouched; the frontmatter keeps only the fields OpenCode knows.

const MARK = 'generated by opencode/install.js';

// Claude Code tool names -> the OpenCode permission action that covers them. An agent whose
// `tools` grants none of a row's names gets a deny rule for that action.
const DENIABLE = [
  ['edit', ['Edit', 'Write', 'MultiEdit', 'NotebookEdit']],
  ['shell', ['Bash', 'PowerShell']],
  ['webfetch', ['WebFetch']],
  ['websearch', ['WebSearch']],
];

const SKILL_FIELDS = ['name', 'description', 'license', 'compatibility', 'metadata', 'disable-model-invocation'];

// Frontmatter fields as [key, raw value] pairs, in order, and the body. Raw values are re-emitted
// as they were written, quoting and escapes included: nothing is re-encoded. An indented line
// continues the previous field.
function splitFrontmatter(text) {
  let src = String(text).replace(/\r\n/g, '\n');
  if (src.charCodeAt(0) === 0xfeff) src = src.slice(1);
  const m = /^---\n([\s\S]*?)\n---(?:\n|$)/.exec(src);
  if (!m) return { fields: [], body: src };
  const fields = [];
  for (const line of m[1].split('\n')) {
    const kv = /^([A-Za-z][\w-]*):(?: (.*))?$/.exec(line);
    if (kv) fields.push([kv[1], kv[2] === undefined ? '' : kv[2]]);
    else if (/^\s/.test(line) && fields.length) fields[fields.length - 1][1] += '\n' + line;
  }
  return { fields, body: src.slice(m[0].length) };
}

function field(fields, key) {
  const hit = fields.find((f) => f[0] === key);
  return hit ? hit[1] : undefined;
}

function emitField(key, raw) {
  return raw.startsWith('\n') ? key + ':' + raw : key + ': ' + raw;
}

function marker(meta) {
  return '<!-- dev-workflow-core ' + meta.version + ': ' + MARK + ' from ' + meta.source +
         '. Edit the source and run the installer again: this copy is overwritten. -->';
}

function assemble(header, meta, body) {
  return ['---'].concat(header, ['---', '', marker(meta), '', body.replace(/^\n+/, '')]).join('\n');
}

// The deny rules for an agent's `tools` line, or [] when it has none (everything inherited).
function denyRules(tools) {
  if (tools === undefined) return [];
  const granted = new Set(tools.replace(/[[\]"']/g, '').split(',').map((s) => s.trim()).filter(Boolean));
  const denied = DENIABLE.filter((row) => !row[1].some((name) => granted.has(name))).map((row) => row[0]);
  if (denied.length === 0) return [];
  const lines = ['permissions:'];
  denied.forEach((action) => lines.push('  - action: ' + action, '    resource: "*"', '    effect: deny'));
  return lines;
}

function agent(text, meta) {
  const { fields, body } = splitFrontmatter(text);
  const header = [];
  const description = field(fields, 'description');
  if (description !== undefined) header.push(emitField('description', description));
  header.push('mode: subagent');
  return assemble(header.concat(denyRules(field(fields, 'tools'))), meta, body);
}

function opencodeNote(root) {
  return [
    '> **In OpenCode.** This command was written for Claude Code: read "Claude Code" as "OpenCode"',
    '> below. In step 5, skip `enabledPlugins` and the restart. In OpenCode the hooks come from the',
    '> dev-workflow-core plugin that `opencode/install.js` installed, and the scripts read',
    '> `.claude/dev-workflow.json` on every call, so a new configuration applies at once. The',
    '> scripts named below are in `' + root + '/hooks/scripts/`.',
    '',
  ].join('\n');
}

function command(text, meta) {
  const { fields, body } = splitFrontmatter(text);
  const root = String(meta.root).split('\\').join('/');
  const description = field(fields, 'description');
  const header = description === undefined ? [] : [emitField('description', description)];
  const resolved = body.split('${CLAUDE_PLUGIN_ROOT}').join(root);
  return assemble(header, meta, opencodeNote(root) + '\n' + resolved.replace(/^\n+/, ''));
}

function skill(text, meta) {
  const { fields, body } = splitFrontmatter(text);
  const header = fields.filter((f) => SKILL_FIELDS.includes(f[0])).map((f) => emitField(f[0], f[1]));
  return assemble(header, meta, body);
}

// The plugin file OpenCode discovers in its plugins/ folder: a pointer to the clone, so the hooks
// follow `git pull` without reinstalling.
function pluginPointer(meta, indexUrl) {
  return [
    '// dev-workflow-core ' + meta.version + ': ' + MARK + '. It points at the clone below, so the',
    '// hooks follow its updates. Run the installer again if the clone moves.',
    'export { default } from ' + JSON.stringify(indexUrl) + ';',
    '',
  ].join('\n');
}

module.exports = { MARK, splitFrontmatter, agent, command, skill, pluginPointer };
